#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class ProvenanceSelectionQuery(global::System.Func<global::CardGame.Core.RuntimeEntries.CoreGameEngineDiscardedProvenanceEntries> getCoreGameEngineDiscardedProvenanceRuntime, global::CardGame.Core.EngineStates.CoreMatchParticipantsState matchParticipantsState, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreGameEngineProgramCardPoliciesEntries> getCoreGameEngineProgramCardPoliciesRuntime, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreGameEngineNationalSkillsEntries> getCoreGameEngineNationalSkillsRuntime, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreGameEngineCardConversionsEntries> getCoreGameEngineCardConversionsRuntime, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreTableSeatQueriesEntries> getCoreTableSeatQueriesRuntime, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreNativeTargetLegalityEntries> getCoreNativeTargetLegalityRuntime, global::System.Func<global::CardGame.Core.RuntimeEntries.CoreGameEngineGuanHaiBridgesEntries> getCoreGameEngineGuanHaiBridgesRuntime) : IProvenanceSelectionQuery
{
    public bool TracksProvenance => getCoreGameEngineDiscardedProvenanceRuntime().TracksDiscardedEntityProvenance;

    public bool IsFaceDown(int ownerSeat) => matchParticipantsState.ReferenceToPlayers[ownerSeat].IsFaceDown;
    public bool HasClaimedEntityPolicy(int ownerSeat) => getCoreGameEngineProgramCardPoliciesRuntime().CardPolicies(matchParticipantsState.ReferenceToPlayers[ownerSeat], SkillProgramCardPolicyKind.ClaimedEntitiesFaceDownUse).Any();
    public string SkillInstance(int ownerSeat, string skillId) => getCoreGameEngineNationalSkillsRuntime().GetRuntimeSkillInstanceId(matchParticipantsState.ReferenceToPlayers[ownerSeat], skillId);
    public ProgramMultiCardViewAsSelection? FindSelection(int ownerSeat, IReadOnlyList<int> cards, CardKind kind, CardConversionSource source) => ProgramSelectionProjection.Freeze(getCoreGameEngineCardConversionsRuntime().FindProgramMultiCardViewAsSelection(matchParticipantsState.ReferenceToPlayers[ownerSeat], cards, kind, false, source));
    public bool IsValidSeat(int seat) => getCoreTableSeatQueriesRuntime().IsValidPlayerSeat(seat);
    public bool CanUseSlash(int ownerSeat, int targetSeat, ProgramMultiCardViewAsSelection selection) => getCoreNativeTargetLegalityRuntime().CanUseVirtualSlashTarget(matchParticipantsState.ReferenceToPlayers[ownerSeat], matchParticipantsState.ReferenceToPlayers[targetSeat], physicalSuit: getCoreGameEngineGuanHaiBridgesRuntime().ProgramMultiCardSuit(matchParticipantsState.ReferenceToPlayers[ownerSeat], selection), effectiveColor: getCoreGameEngineGuanHaiBridgesRuntime().ProgramMultiCardColor(matchParticipantsState.ReferenceToPlayers[ownerSeat], selection), physicalCardIds: selection.Cards.Select(card => card.Id).ToArray());
}
